// HAND-WRITTEN Scala 2.13, compiled by Scala 2.13 + scala-wasm's compiler plugin (wasm/build.sbt, `witGlue`).
//
// WHY this file is Scala 2.13 and not Scala 3: mainline Scala 3 (every nightly included) has no WIT codegen. A WIT
// import is lowered at the CALL SITE by the compiler backend and `@WitExport` is compiler-emitted, so every call to
// an import and every export must be compiled by the WIT-aware 2.13 compiler. The wit-bindgen-scala BINDINGS
// (records, variants, enums, the `@WitImport` defs; package `dapr4swit`) are generated by the scala-wasm plugin
// (`scalaJSWitDirectory`); the 2.13 glue on top of them is this small, hand-written file plus the trampolines in
// src/wasm/glue-exports. It covers only what the Scala 3 wall uses. See wiki/scala-js/scala-wasm-component-spike.md
// (the two-compiler constraint).
//
// The Scala 3 wall (src/wasm/internal) depends on the plain TRAITS below, never on the import functions, and gets the
// live objects only in WasmRuntime: that is what keeps its error mapping unit-testable with fakes (test/wasm/unit).
package dapr4s.internal.witglue

import scala.scalajs.wit

import dapr4swit.dapr_wasm_components.interfaces.{actors, conversation, jobs, jobs_read, state, state_read, types}
import dapr4swit.exports.dapr_wasm_components.interfaces.{
  actors_callback,
  bindings_callback,
  configuration_callback,
  health_callback,
  invocation_callback,
  jobs_callback,
  pubsub_callback,
}

// ---------------------------------------------------------------------------------------------------------------
// Imports the wall calls: one trait per WIT interface, whose companion object is the live implementation (its
// bodies are the only import call sites, so this compiler lowers them).
// ---------------------------------------------------------------------------------------------------------------

/** `dapr-wasm-components:interfaces/state-read@0.7.5`. */
trait StateReadImports {
  def get(
      storeName: String,
      key: String,
      consistency: wit.Option[state_read.Consistency],
      metadata: types.Metadata,
  ): wit.Result[state_read.GetStateResponse, state_read.GetError]
  def getBulk(
      storeName: String,
      keys: Array[String],
      parallelism: wit.Option[wit.unsigned.UInt],
      metadata: types.Metadata,
  ): wit.Result[Array[state_read.BulkStateItem], state_read.StateError]
  def query(
      storeName: String,
      query: types.Json,
      metadata: types.Metadata,
  ): wit.Result[state_read.QueryResponse, state_read.QueryError]
}
object StateReadImports extends StateReadImports {
  override def get(
      storeName: String,
      key: String,
      consistency: wit.Option[state_read.Consistency],
      metadata: types.Metadata,
  ): wit.Result[state_read.GetStateResponse, state_read.GetError] =
    state_read.get(storeName, key, consistency, metadata)
  override def getBulk(
      storeName: String,
      keys: Array[String],
      parallelism: wit.Option[wit.unsigned.UInt],
      metadata: types.Metadata,
  ): wit.Result[Array[state_read.BulkStateItem], state_read.StateError] =
    state_read.getBulk(storeName, keys, parallelism, metadata)
  override def query(
      storeName: String,
      query: types.Json,
      metadata: types.Metadata,
  ): wit.Result[state_read.QueryResponse, state_read.QueryError] =
    state_read.query(storeName, query, metadata)
}

/** `dapr-wasm-components:interfaces/state@0.7.5`. */
trait StateImports {
  def save(
      storeName: String,
      items: Array[state_read.StateItem],
      metadata: types.Metadata,
  ): wit.Result[Unit, state.WriteError]
  def delete(
      storeName: String,
      key: String,
      etag: wit.Option[String],
      options: wit.Option[state_read.StateOptions],
      metadata: types.Metadata,
  ): wit.Result[Unit, state.WriteError]
  def executeTransaction(
      storeName: String,
      operations: Array[state.TransactionRequest],
      metadata: types.Metadata,
  ): wit.Result[Unit, state.TransactionError]
}
object StateImports extends StateImports {
  override def save(
      storeName: String,
      items: Array[state_read.StateItem],
      metadata: types.Metadata,
  ): wit.Result[Unit, state.WriteError] =
    state.save(storeName, items, metadata)
  override def delete(
      storeName: String,
      key: String,
      etag: wit.Option[String],
      options: wit.Option[state_read.StateOptions],
      metadata: types.Metadata,
  ): wit.Result[Unit, state.WriteError] =
    state.delete(storeName, key, etag, options, metadata)
  override def executeTransaction(
      storeName: String,
      operations: Array[state.TransactionRequest],
      metadata: types.Metadata,
  ): wit.Result[Unit, state.TransactionError] =
    state.executeTransaction(storeName, operations, metadata)
}

/** The imports whose flattened params exceed MAX_FLAT_PARAMS = 16, so the canonical ABI passes them through linear
  * memory — which the released scala-wasm linker does not implement (dapr4s-wasm-linker does). The wall does not use
  * them yet; test/wasm/imports-probe calls each one to prove the patched linker lowers them (scripts/wasm/e2e.sh).
  * `jobs.schedule` (`dapr-wasm-components:interfaces/jobs@0.7.5`).
  */
trait JobsImports {
  def schedule(name: String, job: jobs_read.Job, overwrite: Boolean): wit.Result[Unit, jobs.ScheduleError]
}
object JobsImports extends JobsImports {
  override def schedule(name: String, job: jobs_read.Job, overwrite: Boolean): wit.Result[Unit, jobs.ScheduleError] =
    jobs.schedule(name, job, overwrite)
}

/** `conversation.converse` (`dapr-wasm-components:interfaces/conversation@0.7.5`); see [[JobsImports]]. */
trait ConversationImports {
  def converse(
      componentName: String,
      inputs: Array[conversation.ConversationInput],
      options: wit.Option[conversation.ConversationOptions],
  ): wit.Result[conversation.ConversationResponse, conversation.ConverseError]
}
object ConversationImports extends ConversationImports {
  override def converse(
      componentName: String,
      inputs: Array[conversation.ConversationInput],
      options: wit.Option[conversation.ConversationOptions],
  ): wit.Result[conversation.ConversationResponse, conversation.ConverseError] =
    conversation.converse(componentName, inputs, options)
}

/** `actors.register-reminder` / `register-timer` (`dapr-wasm-components:interfaces/actors@0.7.5`); see [[JobsImports]].
  */
trait ActorsImports {
  def registerReminder(
      actorType: String,
      actorId: String,
      name: String,
      reminder: actors.Reminder,
  ): wit.Result[Unit, actors.ActorsError]
  def registerTimer(
      actorType: String,
      actorId: String,
      name: String,
      timer: actors.Timer,
  ): wit.Result[Unit, actors.ActorsError]
}
object ActorsImports extends ActorsImports {
  override def registerReminder(
      actorType: String,
      actorId: String,
      name: String,
      reminder: actors.Reminder,
  ): wit.Result[Unit, actors.ActorsError] =
    actors.registerReminder(actorType, actorId, name, reminder)
  override def registerTimer(
      actorType: String,
      actorId: String,
      name: String,
      timer: actors.Timer,
  ): wit.Result[Unit, actors.ActorsError] =
    actors.registerTimer(actorType, actorId, name, timer)
}

// ---------------------------------------------------------------------------------------------------------------
// The 7 exported `*-callback` interfaces of world `app` (all mandatory), as plain traits. The Scala 3 side implements
// them (src/wasm/internal, src/wasm/inert); the `@WitExport` trampolines (src/wasm/glue-exports) delegate to them
// through the fixed-name object `AppRoot`.
// ---------------------------------------------------------------------------------------------------------------

trait InvocationCallbackExports {
  def onInvoke(request: invocation_callback.InvokeRequest): invocation_callback.HttpResponse
}

trait PubsubCallbackExports {
  def listTopicSubscriptions(): Array[pubsub_callback.TopicSubscription]
  def onTopicEvent(event: pubsub_callback.TopicEvent): pubsub_callback.TopicEventResponse
  def onBulkTopicEvent(event: pubsub_callback.BulkTopicEvent): Array[pubsub_callback.BulkTopicEventEntryResponse]
}

trait BindingsCallbackExports {
  def listInputBindings(): Array[String]
  def onBindingEvent(
      event: bindings_callback.BindingEvent,
  ): wit.Result[bindings_callback.BindingEventResponse, bindings_callback.AppError]
}

trait JobsCallbackExports {
  def onJobEvent(event: jobs_callback.JobEvent): wit.Result[Unit, jobs_callback.AppError]
}

trait ActorsCallbackExports {
  def config(): actors_callback.ActorConfig
  def onInvoke(
      actorType: String,
      actorId: String,
      method: String,
      data: Array[wit.unsigned.UByte],
  ): wit.Result[Array[wit.unsigned.UByte], actors_callback.AppError]
  def onTimer(event: actors_callback.ActorTimerEvent): wit.Result[Unit, actors_callback.AppError]
  def onReminder(event: actors_callback.ActorReminderEvent): wit.Result[Unit, actors_callback.AppError]
  def deactivate(actorType: String, actorId: String): wit.Result[Unit, actors_callback.AppError]
}

trait ConfigurationCallbackExports {
  def onConfigurationEvent(update: configuration_callback.ConfigurationUpdate): Unit
}

trait HealthCallbackExports {
  def healthCheck(): wit.Result[Unit, health_callback.AppError]
}
